class Solution { private int answer=0;private int[] dfs(TreeNode node){if(node==null)return new int[]{1,Integer.MAX_VALUE,Integer.MIN_VALUE,0};int[] left=dfs(node.left),right=dfs(node.right);if(left[0]==1&&right[0]==1&&node.val>left[2]&&node.val<right[1]){int sum=left[3]+right[3]+node.val;answer=Math.max(answer,sum);return new int[]{1,Math.min(node.val,left[1]),Math.max(node.val,right[2]),sum};}return new int[]{0,0,0,0};}public int maxSumBST(TreeNode root){dfs(root);return answer;} }
